function validate([expression, evalvars, evalints]) {
  if (typeof expression !== 'string' || expression.length < 1 || expression.length > 250) return 'expression needs 1 to 250 characters.';
  if (!/^[a-z0-9+\-*() ]+$/.test(expression)) return 'expression may only use lowercase letters, digits, + - * ( ) and spaces.';
  if (!Array.isArray(evalvars) || evalvars.length > 100) return 'evalvars holds at most 100 names.';
  if (!Array.isArray(evalints) || evalints.length !== evalvars.length) return 'evalints needs one value for each name in evalvars.';
  if (evalvars.some(v => typeof v !== 'string' || !/^[a-z]{1,20}$/.test(v))) return 'Each name in evalvars has 1 to 20 lowercase letters.';
  if (new Set(evalvars).size !== evalvars.length) return 'The names in evalvars must be distinct.';
  if (evalints.some(v => !Number.isInteger(v) || v < -100 || v > 100)) return 'Each value in evalints is an integer from -100 to 100.';
  const pieces = expression.split(' ');
  if (pieces.length % 2 === 0) return 'Chunks and operators must alternate, separated by single spaces.';
  let depth = 0;
  for (let i = 0; i < pieces.length; i++) {
    if (i % 2 === 1) {
      if (!['+', '-', '*'].includes(pieces[i])) return 'Chunks and operators must alternate, separated by single spaces.';
      continue;
    }
    const match = /^(\(*)([a-z]+|[0-9]+)(\)*)$/.exec(pieces[i]);
    if (!match) return 'Each chunk is a variable or a number, with any parentheses written against it.';
    depth += match[1].length - match[3].length;
    if (depth < 0) return 'The parentheses are unbalanced.';
  }
  if (depth !== 0) return 'The parentheses are unbalanced.';
  // Expand the polynomial to check the 32-bit guarantee and keep the size reasonable.
  const values = new Map(evalvars.map((v, i) => [v, evalints[i]]));
  const tokens = expression.match(/[a-z]+|[0-9]+|[-+*()]/g);
  let pos = 0, problem = null;
  const check = poly => {
    if (poly.size > 5000) problem = problem || 'The expression expands into too many terms for the local judge.';
    for (const c of poly.values()) if (c < -2147483648 || c > 2147483647) problem = problem || 'An intermediate coefficient leaves the 32-bit integer range.';
    return poly;
  };
  const merge = (a, b, sign) => { const out = new Map(a); for (const [k, c] of b) out.set(k, (out.get(k) || 0) + sign * c); return check(out); };
  const times = (a, b) => {
    const out = new Map();
    if (a.size * b.size > 25000000) { problem = problem || 'The expression expands into too many terms for the local judge.'; return out; }
    for (const [ka, ca] of a) for (const [kb, cb] of b) { const k = (ka + '*' + kb).split('*').filter(Boolean).sort().join('*'); out.set(k, (out.get(k) || 0) + ca * cb); }
    return check(out);
  };
  const parseExpr = () => {
    let poly = parseTerm();
    while (!problem && (tokens[pos] === '+' || tokens[pos] === '-')) { const sign = tokens[pos++] === '+' ? 1 : -1; poly = merge(poly, parseTerm(), sign); }
    return poly;
  };
  const parseTerm = () => {
    let poly = parseFactor();
    while (!problem && tokens[pos] === '*') { pos++; poly = times(poly, parseFactor()); }
    return poly;
  };
  const parseFactor = () => {
    const t = tokens[pos++];
    if (t === '(') { const inner = parseExpr(); pos++; return inner; }
    if (/^[0-9]/.test(t)) return check(new Map([['', Number(t)]]));
    return new Map(values.has(t) ? [['', values.get(t)]] : [[t, 1]]);
  };
  parseExpr();
  return problem;
}

