function basicCalculatorIV(expression, evalvars, evalints) {
  const values = new Map();
  for (let i = 0; i < evalvars.length; i++) values.set(evalvars[i], evalints[i]);
  const rank = new Map([['+', 1], ['-', 1], ['*', 2]]);
  const polys = [];
  const ops = [];

  const combine = (left, right, op) => {
    const result = new Map();
    const add = (key, coef) => result.set(key, (result.get(key) ?? 0) + coef);
    if (op === '*') {
      for (const [leftKey, leftCoef] of left) {
        for (const [rightKey, rightCoef] of right) {
          const vars = `${leftKey}*${rightKey}`.split('*').filter(Boolean).sort();
          add(vars.join('*'), leftCoef * rightCoef);
        }
      }
    } else {
      for (const [key, coef] of left) add(key, coef);
      for (const [key, coef] of right) add(key, op === '+' ? coef : -coef);
    }
    return result;
  };
  const applyTop = () => {
    const op = ops.pop();
    const right = polys.pop();
    const left = polys.pop();
    polys.push(combine(left, right, op));
  };

  for (const token of expression.match(/[a-z]+|\d+|[-+*()]/g)) {
    if (token === '(') {
      ops.push(token);
    } else if (token === ')') {
      while (ops.at(-1) !== '(') applyTop();
      ops.pop();
    } else if (rank.has(token)) {
      while (ops.length > 0 && ops.at(-1) !== '(' && rank.get(ops.at(-1)) >= rank.get(token)) applyTop();
      ops.push(token);
    } else if (/^\d+$/.test(token)) {
      polys.push(new Map([['', Number(token)]]));
    } else if (values.has(token)) {
      polys.push(new Map([['', values.get(token)]]));
    } else {
      polys.push(new Map([[token, 1]]));
    }
  }
  while (ops.length > 0) applyTop();

  const degree = key => (key === '' ? 0 : key.split('*').length);
  const terms = [...polys[0]].filter(([, coef]) => coef !== 0);
  terms.sort(([keyA], [keyB]) => degree(keyB) - degree(keyA) || (keyA < keyB ? -1 : 1));
  return terms.map(([key, coef]) => (key === '' ? `${coef}` : `${coef}*${key}`));
}

