function basicCalculatorIV(expression, evalvars, evalints) {
  const env = {};
  evalvars.forEach((name, i) => { env[name] = evalints[i]; });
  const tokens = expression.replace(/\(/g, '( ').replace(/\)/g, ' )').split(' ');
  let pos = 0;
  // Recursive descent; a polynomial is an unmerged list of monomials { c, v } with v a list of names.
  const parseExpr = () => {
    let out = parseTerm();
    while (tokens[pos] === '+' || tokens[pos] === '-') {
      const sign = tokens[pos++] === '+' ? 1 : -1;
      out = out.concat(parseTerm().map(m => ({ c: sign * m.c, v: m.v })));
    }
    return out;
  };
  const parseTerm = () => {
    let out = parseFactor();
    while (tokens[pos] === '*') {
      pos++;
      const right = parseFactor();
      const next = [];
      for (const a of out) for (const b of right) next.push({ c: a.c * b.c, v: a.v.concat(b.v) });
      out = next;
    }
    return out;
  };
  const parseFactor = () => {
    const t = tokens[pos++];
    if (t === '(') { const inner = parseExpr(); pos++; return inner; }
    if (/^[0-9]+$/.test(t)) return [{ c: parseInt(t, 10), v: [] }];
    if (Object.prototype.hasOwnProperty.call(env, t)) return [{ c: env[t], v: [] }];
    return [{ c: 1, v: [t] }];
  };
  const merged = {};
  for (const m of parseExpr()) {
    const k = JSON.stringify(m.v.slice().sort());
    merged[k] = (merged[k] || 0) + m.c;
  }
  const lists = Object.keys(merged).filter(k => merged[k] !== 0).map(k => JSON.parse(k));
  lists.sort((x, y) => {
    if (x.length !== y.length) return y.length - x.length;
    for (let i = 0; i < x.length; i++) if (x[i] !== y[i]) return x[i] < y[i] ? -1 : 1;
    return 0;
  });
  return lists.map(v => [String(merged[JSON.stringify(v)]), ...v].join('*'));
}

