function generate(rand, size) {
  const large = size === 'large';
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = large ? ['a', 'b', 'c', 'e', 'x', 'y', 'ab', 'ba', 'aa', 'temperature', 'pressure', 'foo'] : ['a', 'b', 'c', 'ab', 'x'];
  const maxLength = large ? 250 : 45;
  for (;;) {
    const evalvars = names.filter(() => rand() < 0.3);
    if (rand() < 0.3) evalvars.push('unused');
    const evalints = evalvars.map(() => Math.floor(rand() * (large ? 201 : 11)) - (large ? 100 : 5));
    const value = new Map(evalvars.map((name, i) => [name, evalints[i]]));
    // Each part reports its text, a bound on the sum of |coefficients| and a bound on its number of terms.
    let peak = 0;
    let most = 0;
    const note = (weight, terms) => { peak = Math.max(peak, weight); most = Math.max(most, terms); };
    const atom = () => {
      if (rand() < 0.35) { const n = Math.floor(rand() * (large ? 30 : 10)); return { text: String(n), weight: n, terms: 1 }; }
      const name = pick(names);
      return { text: name, weight: value.has(name) ? Math.abs(value.get(name)) : 1, terms: 1 };
    };
    const expr = depth => {
      const parts = [];
      const count = 1 + Math.floor(rand() * (large ? 4 : 3));
      for (let i = 0; i < count; i++) parts.push(term(depth));
      let weight = 0, terms = 0, text = '';
      parts.forEach((part, i) => { weight += part.weight; terms += part.terms; note(weight, terms); text += (i ? (rand() < 0.5 ? ' + ' : ' - ') : '') + part.text; });
      return { text, weight, terms };
    };
    const term = depth => {
      const count = 1 + Math.floor(rand() * 3);
      let weight = 1, terms = 1, text = '';
      for (let i = 0; i < count; i++) {
        const part = depth > 0 && rand() < 0.35 ? (sub => ({ ...sub, text: `(${sub.text})` }))(expr(depth - 1)) : atom();
        weight *= part.weight; terms *= part.terms; note(weight, terms);
        text += (i ? ' * ' : '') + part.text;
      }
      return { text, weight, terms };
    };
    const root = expr(large ? 3 : 2);
    if (root.text.length > maxLength || peak > 2147483647 || most > 2000) continue;
    if (large && root.text.length < 150) continue;
    return [root.text, evalvars, evalints];
  }
}
